async () => {
window.gameState.globalVariables.guard_off = true; const m=window.MinigameFramework.currentMinigame; if (m && m._sceneType==='person-chat') window.MinigameFramework.endMinigame(false); return 'guard calm';

}

async () => {
const c=window.phoneRinger.current(); return !!c && c.npcId==='caller_basic' && c.state==='ringing';

}

async () => {
const b = document.querySelector('.incoming-call-decline'); if (!b) return 'no decline button'; b.click(); return 'declined';

}

async () => {
const c=document.querySelector('.contact-item[data-npc-id="hidden_contact"]'); if(!c) return 'no contact hidden_contact'; c.click(); return 'opened hidden_contact';

}

async () => {
const bar=document.getElementById('call-status-bar'); const cap=document.getElementById('call-caption'); const choices=[...document.querySelectorAll('.choice-button')].map(b=>b.innerText.trim()); const btn=document.querySelector('.call-button'); const name=document.querySelector('.conversation-header .contact-name, .conversation-info')?.innerText; return {name, bar: bar?bar.innerText.replace(/\n+/g,' | '):null, caption: cap?cap.innerText:null, choices, callButton: btn?btn.innerText.trim():null};

}

